    "title": "[分享创造] 1. 做了 7 年前端，今年出来独立接活，网站刚上线，顺便聊聊报价和踩过的坑",
    "link": "https://www.v2ex.com/t/1243437#reply0",
    "pub_date": "2026-09-20 17:51:13",
