    "pub_date": "2026-09-20 17:36:05",
    "author": "helianling",
    "description": "这两天 Jev 很热，相关项目也越来越多，但案例散在 X 、GitHub 和各种帖子里，找起来比较麻烦。 我整理了一个 Awesome JEV ，目前收录 100+ jev 相关的项目和案例，分成 10 个类别，包括 Agent 工作流、浏览器操作、SDK 集成、模型路由、搜索与数据、安全审核等。 每个项目都尽量保留公开仓库和对应的源码证据，可以直接查看 JEV 在项目中具体负责什么判断。 项目地址： https://github.co…",
    "content": "这两天 Jev 很热，相关项目也越来越多，但案例散在 X 、GitHub 和各种帖子里，找起来比较麻烦。 我整理了一个 Awesome JEV ，目前收录 100+ jev 相关的项目和案例，分成 10 个类别，包括 Agent 工作流、浏览器操作、SDK 集成、模型路由、搜索与数据、安全审核等。 每个项目都尽量保留公开仓库和对应的源码证据，可以直接查看 JEV 在项目中具体负责什么判断。 项目地址： https://github.com/BeatAPI/awesome-jev 现在还在持续补充，欢迎推荐遗漏的项目…"
