    "content": "链接 ： https://github.com/WsTe47/mylife 想解决的问题 ：用 AI 来引导思考、辅助决策。 想法来源 ：在思考自身职业规划 是否跳槽时，陷入纠结。发现走、不走，都有足够的理由去支撑。但自己到底为什么想走、却反而说不清。因此某天深夜沉思，语音输入 1h 输出了大概 1.3 万字的文档，将心中碎碎念全部吐出记录。第二天摸鱼一想，让 AI 分析了一下此篇文章，发现他能从我的说话频率等多方面总结，且点出部分自我矛盾的地方，结论竟真的十分符合我内心所想。 因此扩展思考，人总是会经常遇到这样纠…"
