    "description": "湾升明月，心安为港，山海盼归，我们一家。“湾区升明月”大湾区电影音乐晚会始终坚持立足粤港澳大湾区文化特色，厚植中华优秀传统文化，积极传递中国时代新声。来自海峡两岸暨香港澳门地区以及海外多国的百余位电影人、音乐人，将齐聚“湾区升明月”2026大湾区电影音乐晚会，以光影之声唱响全球华人“我们一家”的心声，在中秋、国庆双节来临之际共同绘就湾区最美“人间银河”。",
