    "content": "在9月20日国新办“开局起步‘十五五’”系列主题新闻发布会上，市场监管总局规划和财务司司长王国伟现场公布了“清风铁纪”教育整顿的举报平台，“欢迎社会各界对我们的执法队伍进行监督。对于举报查实的问题，我们发现一起、处理一起，绝不护短、绝不姑息。” 王国伟提到，深入排查行政执法队伍中的问题，主要聚焦两个方面：一是有案不立、违法不查；二是粗暴执法、随意执法。这两个方面的问题，已经排查了3523个、通报典型案例384个。 市场监管部门公布“清风铁纪”举报平台，主动把执法队伍置于社会监督之下，体现直面问题、刀刃向内、依法行政…"
