    "content": "自2009年启动第二次全国土地调查，至2022年全国国土变更调查，咸安区有15.32万亩耕地流向林地，仅有3.59万亩林地变为耕地，净差值11.73万亩。 耕地转为林地如此普遍，“实际上很难管”，各级政府部门曾经允许、鼓励发展林特经济，栽种经济林木的行为有其政策依据。 南方周末记者 翟星理 南方周末实习生 王含琦 责任编辑：钱昊平 2026年9月10日，湖北省咸宁市咸安区双溪桥镇毛祠村村民在“林耕置换”整理出的连片耕地上劳作。（南方周末记者翟星理|摄） 2026年9月10日下午，廖鹏开着一辆小货车来到村头刚翻耕的一…"
