    "title": "记者走进四川盐边泥石流搜救核心现场：搜救仍在继续",
    "link": "http://www.news.cn/20260920/9b175b23c0314792905ca0e4f474cfe5/c.html",
    "pub_date": "2026-09-20 16:46:13",
    "author": "杨进,刘坤",
    "description": "受局部强降雨影响，9月19日凌晨，四川省盐边县格萨拉乡支六河村石家沟隧道附近发生泥石流险情。截至发稿，救援人员搜救到2名失联人员，已无生命体征；其余3名失联人员正在全力搜救中。险情发生后，盐边县迅速启动突发地质灾害二级应急响应，各项搜救和应急处置工作正有序开展。新华社记者深入泥石流搜救核心区域，带来最新现场报道。 记者：杨进、刘坤 新华社音视频部制作",
    "content": "受局部强降雨影响，9月19日凌晨，四川省盐边县格萨拉乡支六河村石家沟隧道附近发生泥石流险情。截至发稿，救援人员搜救到2名失联人员，已无生命体征；其余3名失联人员正在全力搜救中。险情发生后，盐边县迅速启动突发地质灾害二级应急响应，各项搜救和应急处置工作正有序开展。新华社记者深入泥石流搜救核心区域，带来最新现场报道。 记者：杨进、刘坤 新华社音视频部制作"
