    "title": "专家研讨电影《江西大旅社》：聚焦南昌起义壮阔历程",
    "link": "http://www.news.cn/20260920/9216e81d47f940619787a009e1bea595/c.html",
    "pub_date": "2026-09-20 16:39:19",
    "author": "邢拓",
    "description": "由江西省委宣传部指导，中国文联电影艺术中心等主办的纪录电影《江西大旅社》创作研讨会日前在京举行。影片以“江西大旅社”为核心叙事空间，聚焦我们党发动南昌起义、打响武装反抗国民党反动派的第一枪的壮阔历程。 据介绍，作为聚焦南昌起义的院线纪录电影，影片创作采用将士抗争与民众觉醒双线叙事结构，以铁轨、剪刀、缝纫机等历史物证为载体，串联九段平民英雄故事。目前影片已完成剧本创作，全面进入筹拍阶段。 多名与会专家表示，《江西大旅社》剧本完整呈现南昌起…",
