    "title": "申联生物：UB-221治疗慢性自发性荨麻疹II期临床试验达到主要终点",
    "link": "https://36kr.com/newsflashes/3991453827988482?f=rss",
    "pub_date": "2026-09-20 15:56:48",
    "author": "",
    "description": "36氪获悉，申联生物公告，公司控股孙公司扬州世之源生物科技有限责任公司自主研发的1类生物药UB-221注射液治疗慢性自发性荨麻疹（CSU）的II期临床研究《一项II期、多中心、随机、双盲、安慰剂对照、平行组研究，以评估UB-221作为添加疗法在慢性自发性荨麻疹（CSU）患者中的疗效，安全性，药代动力学和药效学》达到了主要终点，并取得积极顶线结果。",
    "content": "36氪获悉，申联生物公告，公司控股孙公司扬州世之源生物科技有限责任公司自主研发的1类生物药UB-221注射液治疗慢性自发性荨麻疹（CSU）的II期临床研究《一项II期、多中心、随机、双盲、安慰剂对照、平行组研究，以评估UB-221作为添加疗法在慢性自发性荨麻疹（CSU）患者中的疗效，安全性，药代动力学和药效学》达到了主要终点，并取得积极顶线结果。"
