    "description": "新华社北京9月20日电 记者20日从中国国家铁路集团有限公司获悉，今年1至8月，国家铁路累计发送货物26.9亿吨，日均装车18.74万车，持续保持高位运行，为降低全社会物流成本、保障国民经济平稳运行提供了可靠运输支撑。 今年以来，铁路部门充分发挥全国铁路一张网、运输集中统一调度指挥的优势，加大晋陕蒙新主产区煤炭外运力度，努力确保电煤运输应装尽装，全力支持各地迎峰度夏，1至8月份国家铁路发送煤炭13.89亿吨，其中电煤9.28亿吨，全国铁…",
    "content": "新华社北京9月20日电 记者20日从中国国家铁路集团有限公司获悉，今年1至8月，国家铁路累计发送货物26.9亿吨，日均装车18.74万车，持续保持高位运行，为降低全社会物流成本、保障国民经济平稳运行提供了可靠运输支撑。 今年以来，铁路部门充分发挥全国铁路一张网、运输集中统一调度指挥的优势，加大晋陕蒙新主产区煤炭外运力度，努力确保电煤运输应装尽装，全力支持各地迎峰度夏，1至8月份国家铁路发送煤炭13.89亿吨，其中电煤9.28亿吨，全国铁路直供电厂存煤均保持较高水平。 与此同时，铁路部门对国计民生重点物资运输实行运力…"
