    "description": "当地时间9月19日，针对美媒报道美军在美伊战事中的死亡人数高于官方数据，美国防长赫格塞思称“纯属捏造”。中新社援引《华盛顿邮报》9月18日报道，据五位美方官员透露，至少有22名军人死亡，而这一数字比美国防部公开的数据多了4人。",
