    "description": "中国爱乐乐团开启新音乐季，从2026年9月19日至2027年6月26日，19场演出将汇聚中外音乐名家与青年才俊，以丰富的音乐作品呈现交响艺术的深厚传统与多样面貌。 中外音乐家联袂登台，乐团艺术总监、首席指挥余隆将执棒多场重要演出，吕绍嘉、俞峰、张洁敏等华人指挥家也将分别带来各具特色的曲目。国际指挥阵容包括西尔凡·坎布雷林、克劳斯·彼得·弗洛等名家。独奏家与歌唱家阵容同样令人瞩目，王健、吕思清、黄俊文等活跃于国内外舞台的华人音乐名家，将与…",
    "content": "中国爱乐乐团开启新音乐季，从2026年9月19日至2027年6月26日，19场演出将汇聚中外音乐名家与青年才俊，以丰富的音乐作品呈现交响艺术的深厚传统与多样面貌。 中外音乐家联袂登台，乐团艺术总监、首席指挥余隆将执棒多场重要演出，吕绍嘉、俞峰、张洁敏等华人指挥家也将分别带来各具特色的曲目。国际指挥阵容包括西尔凡·坎布雷林、克劳斯·彼得·弗洛等名家。独奏家与歌唱家阵容同样令人瞩目，王健、吕思清、黄俊文等活跃于国内外舞台的华人音乐名家，将与乐团展开合作。 如何让经典与今天的听众产生联系，是这一音乐季策划的重要出发点。陈…"
