    "description": "新华社北京9月20日电 题：住房公积金新政施行 服务全生命周期住房消费 新华社记者王优玲、郑钧天 住房公积金制度是我国城镇住房制度的重要组成部分，关系到老百姓的切身利益。新修订的《住房公积金管理条例》自9月20日起施行。住房公积金提取情形有哪些新变化？新施行的条例将如何更好满足多样化住房消费需求？ 住房城乡建设部房地产市场监管司司长张雪涛表示，新修订的条例积极顺应我国房地产市场发展变化，以满足缴存人不同阶段多样化住房需求为主要目标，通过…",
    "content": "新华社北京9月20日电 题：住房公积金新政施行 服务全生命周期住房消费 新华社记者王优玲、郑钧天 住房公积金制度是我国城镇住房制度的重要组成部分，关系到老百姓的切身利益。新修订的《住房公积金管理条例》自9月20日起施行。住房公积金提取情形有哪些新变化？新施行的条例将如何更好满足多样化住房消费需求？ 住房城乡建设部房地产市场监管司司长张雪涛表示，新修订的条例积极顺应我国房地产市场发展变化，以满足缴存人不同阶段多样化住房需求为主要目标，通过优化住房公积金缴存、使用、收益和管理，进一步发挥住房公积金制度解决住房问题的重要…"
