    "author": "",
    "description": "中新社北京9月20日电 (记者 马帅莎)据中科宇航消息，北京时间9月20日12时03分，中国在东风商业航天创新试验区使用力箭一号遥十八运载火箭，成功将秦岭卫星01、02星，浦江四号卫星，鹏城首发星，谛听01组A/B/C星，超智算一号卫星，云霄探路者卫星共9颗卫星发射升空，卫星顺利进入预定轨道，发射任务取得圆满成功。",
