    "content": "随着中秋假期和国庆假期的火车票正式开售，多家在线旅游平台的机票、酒店预订量冲上本轮双节周期的峰值，出行相关产品的预订进入高峰期。 去哪儿旅行数据显示，截至9月16日，平台上“中秋”“国庆”等关键词搜索量环比上月增长167%，本周国庆机酒预订量环比上周增长56%。 与往年不同，今年中秋（9月25日至27日）与国庆（10月1日至7日）之间只隔9月28日至30日三个工作日。“请3休13”的拼假方案把两段假期连成最长13天的窗口，预订节奏也随之整体前移。与此同时，“请3休13”催生的“超长版黄金周”带动长线游与奔县深度游同…"
