    "content": "一个AI办公助手，究竟要知道多少关于你的事，才算真的好用？ 在亚马逊云科技上海Builder Loft举行的Amazon Quick媒体工作坊（“Make it Quick”工作坊）上，这个问题反复被提及。 原因很简单。当天正式介绍的Amazon Quick桌面版，的确有相对优势的特点，比如：不再只待在网页里等用户提问。得到授权后，它能读取本地文件、操作浏览器、查看邮件和日历，还会根据这些信息提醒用户：有几封邮件该回了，某个项目需要跟进，昨天安排的任务已经跑完。 这说明了，Amazon Quick的场景，的确离一个…"
